create or replace function public.notify_support_message() returns trigger language plpgsql security definer set search_path=public as $$ declare v_member uuid; v_subject text; begin select member_id,subject into v_member,v_subject from public.member_support_threads where id=new.thread_id; update public.member_support_threads set updated_at=now(),status=case when new.sender_id=v_member then 'open' else 'answered' end where id=new.thread_id; if new.sender_id=v_member then insert into public.member_notifications(user_id,actor_id,kind,title,body,entity_id) select a.user_id,v_member,'support','New support request','A member sent a message: '||left(v_subject,120),new.thread_id from public.admin_users a; else insert into public.member_notifications(user_id,actor_id,kind,title,body,entity_id) values(v_member,new.sender_id,'support','DateMe support replied','There is a new reply in your support conversation.',new.thread_id); end if; return new; end $$; revoke execute on function public.notify_support_message() from anon,authenticated,public; drop trigger if exists notify_support_message_trigger on public.member_support_messages; create trigger notify_support_message_trigger after insert on public.member_support_messages for each row execute function public.notify_support_message(); create or replace function public.notify_verification_review() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status is distinct from old.status and new.status in ('approved','rejected','suspended') then insert into public.member_notifications(user_id,actor_id,kind,title,body,entity_id) values(new.user_id,new.reviewed_by,'verification',case when new.status='approved' then 'Verification approved' when new.status='suspended' then 'Account verification suspended' else 'Verification needs attention' end,case when new.status='approved' then 'Your verification was approved by DateMe.' when new.status='suspended' then 'Your account verification was suspended. Please contact support.' else coalesce(new.review_note,'Your verification needs another review. Please contact support for next steps.') end,new.id); end if; return new; end $$; revoke execute on function public.notify_verification_review() from anon,authenticated,public; drop trigger if exists notify_verification_review_trigger on public.member_verification_submissions; create trigger notify_verification_review_trigger after update of status on public.member_verification_submissions for each row execute function public.notify_verification_review();